import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"ADR-0032 — Task (go-task) al posto di make","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0032-task-runner.md","filePath":"adr/0032-task-runner.md"}'),d={name:"adr/0032-task-runner.md"};function c(s,e,n,l,r,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0032-—-task-go-task-al-posto-di-make" tabindex="-1">ADR-0032 — Task (go-task) al posto di make <a class="header-anchor" href="#adr-0032-—-task-go-task-al-posto-di-make" aria-label="Permalink to &quot;ADR-0032 — Task (go-task) al posto di make&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.3 (2026-11-02): §4.1, §4.5 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-30</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§4.1 (Monorepo, <code>Makefile</code>) e §4.5 (Convenzioni di sviluppo, <code>make gen</code>) di <code>Specifications.md</code></td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì (§4.1 e §4.5) → <code>Makefile</code> diventa <code>Taskfile.yml</code>, <code>make &lt;target&gt;</code> diventa <code>task &lt;target&gt;</code></td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Gli entry point del monorepo erano in un <code>Makefile</code>. Make non è disponibile di default su Windows (uno dei tre sistemi del client desktop), la sua versione varia tra macOS (GNU make 3.81) e Linux, e la sintassi (tab obbligatori, <code>$$</code>, variabili ricorsive) è fragile. Gli altri tool di sviluppo sono già pinnati come <code>tool</code> in <code>tools/go.mod</code> (ADR-0006).</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ul><li>Gli entry point stanno in <code>Taskfile.yml</code> (Task v3, <code>github.com/go-task/task/v3/cmd/task</code>), con gli stessi nomi dei target del <code>Makefile</code> e la stessa descrizione; il <code>Makefile</code> è rimosso.</li><li>Task è pinnato come <code>tool</code> in <code>tools/go.mod</code> (v3.54.0): bootstrap con <code>cd tools &amp;&amp; GOWORK=off go install github.com/go-task/task/v3/cmd/task</code>; poi <code>task tools</code> reinstalla anche Task con gli altri tool. La CI lo installa nello stesso modo.</li><li>Variabili: <code>task perf PERF_NOTES=10000</code>, <code>task release-desktop OS=darwin V=1.0.0-rc.1</code>, <code>task rename-module NEW=…</code>; anche come variabili d&#39;ambiente (<code>VERSION</code>, <code>IMAGE</code>, <code>PLATFORMS</code>, <code>WEB=0</code> per <code>dev-cloud</code>). Argomenti extra agli script dopo <code>--</code> (<code>task dev-stop -- --stack</code>; resta <code>ARGS=--stack</code>).</li><li><code>task</code> senza argomenti (o <code>task --list</code>) sostituisce <code>make help</code>. Il target file <code>packages/workbench/wailsjs/go/models.ts</code> diventa il task <code>wailsjs</code> (eseguito solo se i binding mancano, via <code>status</code>).</li><li>I target composti (<code>gen</code>, <code>lint</code>, <code>test</code>, <code>e2e</code>, <code>ci</code>, <code>web-build</code>) chiamano i sotto-task in sequenza (<code>cmds</code>, non <code>deps</code>), come faceva make senza <code>-j</code>.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Tenere make</strong> — scartata: non portabile su Windows senza MSYS/WSL.</li><li><strong>Script shell o <code>just</code></strong> — scartata: script ad hoc senza elenco/descrizioni; <code>just</code> non si pinna in <code>tools/go.mod</code> (Rust).</li><li><strong>Mage (Go)</strong> — scartata: più verboso per comandi che sono quasi tutti invocazioni di CLI.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Un passo di bootstrap in più (installare Task) prima di <code>task tools</code>.</li><li>I comandi di Task girano nell&#39;interprete <code>mvdan.cc/sh</code> (POSIX), non in bash: i comandi che richiedono bash (<code>dev-cloud</code>, <code>release-desktop</code>) lo invocano esplicitamente.</li><li>Gli ADR precedenti, il <code>CHANGELOG</code> e <code>Specifications.md</code> citano ancora <code>make &lt;target&gt;</code>: i nomi dei target sono invariati, quindi basta leggere <code>task</code> al posto di <code>make</code>. Lo spec va aggiornato dall&#39;owner.</li></ul><p><strong>Aggiornamento 2026-11-02:</strong> l&#39;owner ha accettato l&#39;ADR, recepito in <code>Specifications.md</code> v1.3 (§4.1, §4.5); lo spec non cita più make. Non c&#39;è più una CI che installi Task (ADR-0036): il bootstrap descritto sopra vale per le verifiche locali.</p>',11)])])}const g=o(d,[["render",c]]);export{m as __pageData,g as default};
